// Stub for `#lib/paraglide/runtime.js` (generated by Paraglide at scaffold time).
// Repo-root tests compile template components that read the configured locales;
// the behaviour mirrors the Paraglide 2 runtime: the base locale is unprefixed,
// de-localizing strips a locale segment, localizing re-adds it.
export let locales = ['en', 'fr'];

export const state = { locale: 'en', base: 'en' };

export function __setLocaleState({ locales: nextLocales, locale, base } = {}) {
	if (nextLocales) locales = [...nextLocales];
	if (locale) state.locale = locale;
	if (base) state.base = base;
}

export function __resetLocaleState() {
	locales = ['en', 'fr'];
	state.locale = 'en';
	state.base = 'en';
}

export function getLocale() {
	return state.locale;
}

export function getTextDirection() {
	return 'ltr';
}

const Url = globalThis.URL;

export function deLocalizeUrl(url) {
	const parsed = url instanceof Url ? url : new Url(url, 'http://localhost');
	const segments = parsed.pathname.split('/');
	if (locales.includes(segments[1])) {
		segments.splice(1, 1);
		const pathname = segments.join('/') || '/';
		return new Url(`${pathname}${parsed.search}${parsed.hash}`, parsed.origin);
	}
	return parsed;
}

export function localizeHref(href, options = {}) {
	if (!href.startsWith('/')) return href;
	const target = options.locale ?? state.locale;
	const canonical = deLocalizeUrl(href).pathname;
	if (target === state.base) return canonical;
	return canonical === '/' ? `/${target}` : `/${target}${canonical}`;
}
